import type { ProgramData, ProgramOrg } from "@/lib/program-data";

/**
 * LFX Mentorship projects outside CNCF, grouped by Linux Foundation project, generated by
 * scripts/programs/collect-lfx-foundations.mjs from the LFX Mentorship platform's public project
 * list and each organization's own GitHub account. The file is committed; pages never fetch live.
 */

export interface FoundationOrg extends ProgramOrg {
  foundation: string;
  lfProject: string;
}

export interface Foundation {
  key: string;
  short: string;
  name: string;
  orgCount: number;
  projectCount: number;
  years: number[];
  orgs: FoundationOrg[];
}

export interface FoundationsFile {
  generatedAt: string;
  note: string;
  sources: { label: string; url: string }[];
  foundations: Foundation[];
}

/** CNCF is the default switch; its data comes from the CNCF mentoring repository (the database). */
export const CNCF_KEY = "cncf";
export const CNCF_NAME = "Cloud Native Computing Foundation";

export async function lfxFoundations(): Promise<FoundationsFile> {
  return (await import("@/data/programs/lfx-foundations.json")).default as FoundationsFile;
}

export async function lfxFoundation(key: string | undefined): Promise<Foundation | null> {
  if (!key) return null;
  return (await lfxFoundations()).foundations.find((f) => f.key === key) ?? null;
}

/** An organization from any non-CNCF foundation, by its slug (slugs carry the foundation key). */
export async function foundationOrg(orgSlug: string) {
  const file = await lfxFoundations();
  const slug = decodeURIComponent(orgSlug);
  for (const f of file.foundations) {
    const org = f.orgs.find((o) => o.slug === slug);
    if (org) return { file, foundation: f, org };
  }
  return null;
}

/** A foundation shaped like a program file, so the shared program components can render it. */
export function foundationAsProgram(file: FoundationsFile, f: Foundation): ProgramData {
  return {
    program: "lfx-mentorship",
    name: `LFX Mentorship · ${f.short === "More" ? "More foundations" : f.short}`,
    generatedAt: file.generatedAt,
    years: f.years,
    note: file.note,
    sources: file.sources,
    orgs: f.orgs,
  };
}
